head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.checkVal = function() {
    //return WebSquare.wUnit.getJq(WebSquare.wUnit.getDomById($p.id+'wq_uuid_1_cell_3_3')).hasClass('w2calendar_selected_week') == true;
    for (var i = 0; i < WebSquare.wUnit.getDomById($p.id + 'wq_uuid_1_content').getElementsByTagName('td').length; i++) {
        if (WebSquare.wUnit.getDomById($p.id + 'wq_uuid_1_content').getElementsByTagName('td')[i].getAttribute('title') == '선택일') {
            return WebSquare.wUnit.getJq(WebSquare.wUnit.getDomById($p.id + 'wq_uuid_1_content').getElementsByTagName('td')[i]).hasClass('w2calendar_selected_week') == true;
        }
    }
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand('pause', '100');
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
